using System.Reflection;
using System.Runtime.CompilerServices;
using System.Runtime.Loader;
public static class ContractTests {
 public static void Register(Action<string,Action> test){
  string game=Environment.GetEnvironmentVariable("RIMWORLD_GAME_DIR")??throw new InvalidOperationException("Set RIMWORLD_GAME_DIR for game contract tests");
  string harmony=Environment.GetEnvironmentVariable("RIMWORLD_HARMONY")??throw new InvalidOperationException("Set RIMWORLD_HARMONY for game contract tests");
  AssemblyLoadContext.Default.Resolving+=(c,n)=>{var p=Path.Combine(game,n.Name+".dll");if(File.Exists(p))return c.LoadFromAssemblyPath(p);if(n.Name=="0Harmony")return c.LoadFromAssemblyPath(harmony);return null;};
  Assembly Mod()=>Assembly.LoadFrom(Path.GetFullPath("bin/Release/net10.0/ResourceLedger.dll"));
  ReviewContractTests.Register(test,Mod,Assembly.LoadFrom(Path.Combine(game,"Assembly-CSharp.dll")));
  test("Minified furniture keeps its actual item type",()=>{var a=Assembly.LoadFrom(Path.Combine(game,"Assembly-CSharp.dll"));var defType=a.GetType("Verse.ThingDef",true)!;var thingType=a.GetType("Verse.Thing",true)!;var miniType=a.GetType("Verse.MinifiedThing")??a.GetType("RimWorld.MinifiedThing",true)!;object MakeDef(string id){var d=RuntimeHelpers.GetUninitializedObject(defType);defType.GetField("defName")!.SetValue(d,id);return d;}var mini=RuntimeHelpers.GetUninitializedObject(miniType);thingType.GetField("def")!.SetValue(mini,MakeDef("MinifiedThing"));var inner=RuntimeHelpers.GetUninitializedObject(thingType);thingType.GetField("def")!.SetValue(inner,MakeDef("Shelf"));var containerType=a.GetType("Verse.ThingOwner`1",true)!.MakeGenericType(thingType);var container=RuntimeHelpers.GetUninitializedObject(containerType);var list=(System.Collections.IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(thingType))!;list.Add(inner);containerType.GetField("innerList",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.SetValue(container,list);miniType.GetField("innerContainer",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(mini,container);var method=Mod().GetType("ResourceLedger.Game.InventoryReader",true)!.GetMethod("ResourceId")??throw new Exception("Actual item identity is unavailable");if((string)method.Invoke(null,new[]{mini})! != "Shelf")throw new Exception("Furniture was collapsed into a generic minified item");});

  test("Non-stackable supplies are automatically eligible",()=>{var a=Assembly.LoadFrom(Path.Combine(game,"Assembly-CSharp.dll"));var defType=a.GetType("Verse.ThingDef",true)!;var def=RuntimeHelpers.GetUninitializedObject(defType);defType.GetField("category")!.SetValue(def,Enum.Parse(a.GetType("Verse.ThingCategory",true)!,"Item"));defType.GetField("stackLimit")!.SetValue(def,1);defType.GetField("thingClass")!.SetValue(def,a.GetType("Verse.Thing",true)!);var eligible=(bool)Mod().GetType("ResourceLedger.Game.InventoryReader",true)!.GetMethod("IsTrackable")!.Invoke(null,new[]{def})!;if(!eligible)throw new Exception("Non-stackable item excluded from tracking");});
  test("Construction capture begins before container removal",()=>{var t=Mod().GetType("ResourceLedger.Game.CapturePatches",true)!;var rows=(System.Collections.IEnumerable)t.GetMethod("Targets")!.Invoke(null,null)!;if(!rows.Cast<object>().Any(x=>((MethodBase)x.GetType().GetField("Method")!.GetValue(x)!).Name=="TryTransferToContainer"))throw new Exception("source-container transfer capture missing");});
  test("Refueling capture wraps the completed toil",()=>{var t=Mod().GetType("ResourceLedger.Game.CapturePatches",true)!;var rows=(System.Collections.IEnumerable)t.GetMethod("Targets")!.Invoke(null,null)!;if(!rows.Cast<object>().Any(x=>((MethodBase)x.GetType().GetField("Method")!.GetValue(x)!).Name=="FinalizeRefueling"))throw new Exception("refuel completion capture missing");});
  test("Snapshot projection distinguishes carried and stored resources",()=>{var a=Mod();var t=a.GetType("ResourceLedger.Game.InventorySnapshot",true)!;var snapshot=Activator.CreateInstance(t)!;t.GetField("Counts")!.SetValue(snapshot,new Dictionary<string,long>{{"Steel",15}});var list=(System.Collections.IList)t.GetField("Items")!.GetValue(snapshot)!;var itemType=a.GetType("ResourceLedger.Game.InventoryItem",true)!;foreach(var (group,count) in new[]{("stock",10L),("",5L)}){var item=Activator.CreateInstance(itemType)!;itemType.GetField("Resource")!.SetValue(item,"Steel");itemType.GetField("Group")!.SetValue(item,group);itemType.GetField("Count")!.SetValue(item,count);list.Add(item);}var mapCounts=(Dictionary<string,long>)t.GetMethod("Project")!.Invoke(snapshot,new object?[]{"map",null})!;var stored=(Dictionary<string,long>)t.GetMethod("Project")!.Invoke(snapshot,new object?[]{"stored",null})!;if(mapCounts["Steel"]!=15||stored["Steel"]!=10)throw new Exception("incorrect scope totals");});
  test("Recipe toil wrapper preserves original exceptions",()=>{var a=Mod();var toilType=Assembly.LoadFrom(Path.Combine(game,"Assembly-CSharp.dll")).GetType("Verse.AI.Toil",true)!;var toil=Activator.CreateInstance(toilType)!;var marker=new InvalidOperationException("original-action");toilType.GetField("initAction")!.SetValue(toil,(Action)(()=>throw marker));a.GetType("ResourceLedger.Game.CapturePatches",true)!.GetMethod("RecipeToilPostfix")!.Invoke(null,new[]{toil});try{((Action)toilType.GetField("initAction")!.GetValue(toil)!)();throw new Exception("original exception swallowed");}catch(InvalidOperationException e){if(!ReferenceEquals(e,marker))throw;}});
  test("Quest deliveries have an explicit capture context",()=>{var t=Mod().GetType("ResourceLedger.Game.CapturePatches",true)!;var rows=(System.Collections.IEnumerable)t.GetMethod("Targets")!.Invoke(null,null)!;if(!rows.Cast<object>().Any(x=>((MethodBase)x.GetType().GetField("Method")!.GetValue(x)!).DeclaringType?.Name=="QuestPart_DropPods"))throw new Exception("quest delivery context missing");});
  test("Game component can be constructed for existing save",()=>{var t=Mod().GetType("ResourceLedger.Game.LedgerGameComponent",true)!;var instance=Activator.CreateInstance(t,new object?[]{null});if(instance==null)throw new Exception("null component");});
  test("UI tab resolves against real 1.7 MainTabWindow",()=>{var t=Mod().GetType("ResourceLedger.UI.LedgerWindow",true)!;if(t.BaseType?.FullName!="RimWorld.MainTabWindow")throw new Exception("wrong base");});
  test("Capture targets all resolve against installed 1.7",()=>{var t=Mod().GetType("ResourceLedger.Game.CapturePatches",true)!;var r=(System.Collections.IEnumerable)t.GetMethod("Targets")!.Invoke(null,null)!;int count=0;foreach(var item in r){var m=(MethodBase?)item!.GetType().GetField("Method")!.GetValue(item);if(m==null)throw new Exception("unresolved target");count++;}if(count<19)throw new Exception("Too few capture targets: "+count);Console.WriteLine("Resolved capture methods: "+count);});
  test("All Harmony patches install on real 1.7 methods in isolated process",()=>{var t=Mod().GetType("ResourceLedger.Game.CapturePatches",true)!;var ht=Assembly.LoadFrom(harmony).GetType("HarmonyLib.Harmony",true)!;var h=Activator.CreateInstance(ht,new object[]{"resourceledger.tests"})!;t.GetMethod("Install")!.Invoke(null,new[]{h});var warnings=(System.Collections.ICollection)t.GetField("Warnings")!.GetValue(null)!;if(warnings.Count!=0)throw new Exception(string.Join(";",((System.Collections.IEnumerable)warnings).Cast<object>()));ht.GetMethod("UnpatchAll",new[]{typeof(string)})!.Invoke(h,new object[]{"resourceledger.tests"});});
 }
}
